public enum Symbol { X, O, EMPTY }

public class Cell {
    private final int row;
    private final int col;
    private Symbol symbol;

    public Cell(int row, int col) {
        this.row = row;
        this.col = col;
        this.symbol = Symbol.EMPTY;
    }
    public boolean isEmpty() { return symbol == Symbol.EMPTY; }
    public Symbol getSymbol() { return symbol; }
    public void setSymbol(Symbol s) { this.symbol = s; }
}

public class Board {
    private final int size;
    private final Cell[][] grid;
    private int filledCount;

    public Board(int size) {
        this.size = size;
        this.grid = new Cell[size][size];
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                grid[r][c] = new Cell(r, c);
            }
        }
        this.filledCount = 0;
    }

    public synchronized boolean applyMove(int r, int c, Symbol symbol) {
        if (r < 0 || r >= size || c < 0 || c >= size || !grid[r][c].isEmpty()) {
            return false;
        }
        grid[r][c].setSymbol(symbol);
        filledCount++;
        return true;
    }

    public boolean isFull() { return filledCount == size * size; }
    public int getSize() { return size; }
    public Cell getCell(int r, int c) { return grid[r][c]; }
}

public interface PlayingStrategy {
    int[] determineMove(Board board, Symbol symbol);
}

public class RandomPlayingStrategy implements PlayingStrategy {
    @Override
    public int[] determineMove(Board board, Symbol symbol) {
        int n = board.getSize();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board.getCell(r, c).isEmpty()) return new int[]{r, c};
            }
        }
        return null;
    }
}

public class O1WinCondition {
    private final int[] rowCount;
    private final int[] colCount;
    private int diagCount;
    private int antiDiagCount;
    private final int target;

    public O1WinCondition(int size) {
        this.target = size;
        this.rowCount = new int[size];
        this.colCount = new int[size];
    }

    public boolean checkWin(int r, int c, Symbol symbol) {
        int val = (symbol == Symbol.X) ? 1 : -1;
        rowCount[r] += val;
        colCount[c] += val;
        if (r == c) diagCount += val;
        if (r + c == target - 1) antiDiagCount += val;

        return Math.abs(rowCount[r]) == target ||
               Math.abs(colCount[c]) == target ||
               Math.abs(diagCount) == target ||
               Math.abs(antiDiagCount) == target;
    }
}

