from enum import Enum
from abc import ABC, abstractmethod
from typing import List, Optional, Tuple

class Symbol(Enum):
    EMPTY = 0
    X = 1
    O = 2

class Board:
    def __init__(self, size: int = 3):
        self.size = size
        self.grid = [[Symbol.EMPTY for _ in range(size)] for _ in range(size)]
        self.filled_count = 0

    def is_valid(self, r: int, c: int) -> bool:
        return 0 <= r < self.size and 0 <= c < self.size and self.grid[r][c] == Symbol.EMPTY

    def apply_move(self, r: int, c: int, symbol: Symbol) -> bool:
        if not self.is_valid(r, c):
            return False
        self.grid[r][c] = symbol
        self.filled_count += 1
        return True

    def is_full(self) -> bool:
        return self.filled_count == self.size * self.size

class PlayingStrategy(ABC):
    @abstractmethod
    def determine_move(self, board: Board, symbol: Symbol) -> Optional[Tuple[int, int]]:
        pass

class RandomStrategy(PlayingStrategy):
    def determine_move(self, board: Board, symbol: Symbol) -> Optional[Tuple[int, int]]:
        for r in range(board.size):
            for c in range(board.size):
                if board.grid[r][c] == Symbol.EMPTY:
                    return (r, c)
        return None

class O1WinChecker:
    def __init__(self, size: int):
        self.n = size
        self.rows = [0] * size
        self.cols = [0] * size
        self.diag = 0
        self.anti_diag = 0

    def check_win(self, r: int, c: int, symbol: Symbol) -> bool:
        val = 1 if symbol == Symbol.X else -1
        self.rows[r] += val
        self.cols[c] += val
        if r == c:
            self.diag += val
        if r + c == self.n - 1:
            self.anti_diag += val
        return (abs(self.rows[r]) == self.n or 
                abs(self.cols[c]) == self.n or 
                abs(self.diag) == self.n or 
                abs(self.anti_diag) == self.n)

