from enum import Enum
from abc import ABC, abstractmethod

class SignalColor(Enum):
    RED = "RED"
    YELLOW = "YELLOW"
    GREEN = "GREEN"

class SignalState(ABC):
    @abstractmethod
    def handle(self, context) -> None:
        pass

    @abstractmethod
    def get_color(self) -> SignalColor:
        pass

    @abstractmethod
    def get_duration(self) -> int:
        pass

class GreenState(SignalState):
    def handle(self, context) -> None:
        context.set_state(YellowState())

    def get_color(self) -> SignalColor:
        return SignalColor.GREEN

    def get_duration(self) -> int:
        return 40

class YellowState(SignalState):
    def handle(self, context) -> None:
        context.set_state(RedState())

    def get_color(self) -> SignalColor:
        return SignalColor.YELLOW

    def get_duration(self) -> int:
        return 5

class RedState(SignalState):
    def handle(self, context) -> None:
        context.set_state(GreenState())

    def get_color(self) -> SignalColor:
        return SignalColor.RED

    def get_duration(self) -> int:
        return 45

class TrafficSignalController:
    def __init__(self):
        self.state: SignalState = RedState()

    def set_state(self, state: SignalState):
        self.state = state

    def transition(self):
        self.state.handle(self)

