public enum PlayerColor { WHITE, BLACK }

public interface IncrementStrategy {
    long applyIncrement(long currentRemainingMs, long elapsedInTurnMs, long incrementMs);
}

public class FischerIncrement implements IncrementStrategy {
    @Override
    public long applyIncrement(long currentRemainingMs, long elapsedInTurnMs, long incrementMs) {
        return currentRemainingMs + incrementMs;
    }
}

public class PlayerTimer {
    private final PlayerColor color;
    private long remainingMs;
    private long turnStartTime;

    public PlayerTimer(PlayerColor color, long initialMs) {
        this.color = color;
        this.remainingMs = initialMs;
    }

    public synchronized void start() {
        this.turnStartTime = System.currentTimeMillis();
    }

    public synchronized long stop(IncrementStrategy strategy, long incrementMs) {
        long elapsed = System.currentTimeMillis() - turnStartTime;
        remainingMs = Math.max(0, remainingMs - elapsed);
        if (remainingMs > 0) {
            remainingMs = strategy.applyIncrement(remainingMs, elapsed, incrementMs);
        }
        return remainingMs;
    }

    public synchronized long getRemainingMs() { return remainingMs; }
    public boolean isFlagged() { return remainingMs <= 0; }
}

public class ChessClock {
    private final PlayerTimer whiteTimer;
    private final PlayerTimer blackTimer;
    private final IncrementStrategy strategy;
    private final long incrementMs;
    private PlayerColor activePlayer;
    private boolean isPaused;

    public ChessClock(long initialMinutes, long incrementSeconds, IncrementStrategy strategy) {
        long ms = initialMinutes * 60 * 1000;
        this.incrementMs = incrementSeconds * 1000;
        this.strategy = strategy;
        this.whiteTimer = new PlayerTimer(PlayerColor.WHITE, ms);
        this.blackTimer = new PlayerTimer(PlayerColor.BLACK, ms);
        this.activePlayer = PlayerColor.WHITE;
        this.isPaused = true;
    }

    public synchronized void start() {
        isPaused = false;
        if (activePlayer == PlayerColor.WHITE) whiteTimer.start();
        else blackTimer.start();
    }

    public synchronized void pressLever(PlayerColor pressingPlayer) {
        if (isPaused || pressingPlayer != activePlayer) return;
        if (activePlayer == PlayerColor.WHITE) {
            whiteTimer.stop(strategy, incrementMs);
            activePlayer = PlayerColor.BLACK;
            blackTimer.start();
        } else {
            blackTimer.stop(strategy, incrementMs);
            activePlayer = PlayerColor.WHITE;
            whiteTimer.start();
        }
    }
}

