enum class PlayerColor { WHITE, BLACK };

class IncrementStrategy {
public:
    virtual ~IncrementStrategy() = default;
    virtual long long applyIncrement(long long remainingMs, long long elapsedMs, long long incMs) = 0;
};

class FischerIncrement : public IncrementStrategy {
public:
    long long applyIncrement(long long remainingMs, long long elapsedMs, long long incMs) override {
        return remainingMs + incMs;
    }
};

class PlayerTimer {
private:
    PlayerColor color;
    long long remainingMs;
    std::chrono::steady_clock::time_point startTime;
    std::mutex mtx;
public:
    PlayerTimer(PlayerColor c, long long initialMs) : color(c), remainingMs(initialMs) {}

    void start() {
        std::lock_guard<std::mutex> lock(mtx);
        startTime = std::chrono::steady_clock::now();
    }

    long long stop(IncrementStrategy* strategy, long long incMs) {
        std::lock_guard<std::mutex> lock(mtx);
        auto now = std::chrono::steady_clock::now();
        long long elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(now - startTime).count();
        remainingMs = std::max(0LL, remainingMs - elapsed);
        if (remainingMs > 0 && strategy) {
            remainingMs = strategy->applyIncrement(remainingMs, elapsed, incMs);
        }
        return remainingMs;
    }

    long long getRemaining() {
        std::lock_guard<std::mutex> lock(mtx);
        return remainingMs;
    }
};

