import time
from enum import Enum
from abc import ABC, abstractmethod
import threading

class PlayerColor(Enum):
    WHITE = 1
    BLACK = 2

class IncrementStrategy(ABC):
    @abstractmethod
    def apply_increment(self, remaining_ms: int, elapsed_ms: int, increment_ms: int) -> int:
        pass

class FischerIncrement(IncrementStrategy):
    def apply_increment(self, remaining_ms: int, elapsed_ms: int, increment_ms: int) -> int:
        return remaining_ms + increment_ms

class PlayerTimer:
    def __init__(self, color: PlayerColor, initial_ms: int):
        self.color = color
        self.remaining_ms = initial_ms
        self.turn_start = 0
        self.lock = threading.Lock()

    def start(self):
        with self.lock:
            self.turn_start = time.time()

    def stop(self, strategy: IncrementStrategy, inc_ms: int) -> int:
        with self.lock:
            elapsed = int((time.time() - self.turn_start) * 1000)
            self.remaining_ms = max(0, self.remaining_ms - elapsed)
            if self.remaining_ms > 0:
                self.remaining_ms = strategy.apply_increment(self.remaining_ms, elapsed, inc_ms)
            return self.remaining_ms

