public enum LogLevel { DEBUG(1), INFO(2), WARN(3), ERROR(4);
    private final int level;
    LogLevel(int l) { this.level = l; }
    public boolean shouldLog(LogLevel target) { return this.level >= target.level; }
}

public interface LogAppender {
    void append(String formattedMessage);
}

public class ConsoleAppender implements LogAppender {
    @Override
    public void append(String msg) { System.out.println(msg); }
}

public abstract class AbstractLogger {
    protected LogLevel level;
    protected AbstractLogger nextLogger;

    public AbstractLogger(LogLevel level) { this.level = level; }
    public void setNext(AbstractLogger next) { this.nextLogger = next; }

    public void log(LogLevel lvl, String message, LogAppender appender) {
        if (this.level.shouldLog(lvl)) {
            write(message, appender);
        }
        if (nextLogger != null) {
            nextLogger.log(lvl, message, appender);
        }
    }
    protected abstract void write(String message, LogAppender appender);
}

public class InfoLogger extends AbstractLogger {
    public InfoLogger() { super(LogLevel.INFO); }
    @Override
    protected void write(String msg, LogAppender appender) {
        appender.append("[INFO] " + System.currentTimeMillis() + " - " + msg);
    }
}

public class ErrorLogger extends AbstractLogger {
    public ErrorLogger() { super(LogLevel.ERROR); }
    @Override
    protected void write(String msg, LogAppender appender) {
        appender.append("[ERROR] " + System.currentTimeMillis() + " - " + msg);
    }
}

