import time

class LogLevel(Enum):
    DEBUG = 1
    INFO = 2
    ERROR = 3

class LogAppender(ABC):
    @abstractmethod
    def append(self, message: str) -> None:
        pass

class ConsoleAppender(LogAppender):
    def append(self, message: str) -> None:
        print(message)

class AbstractLogger(ABC):
    def __init__(self, level: LogLevel):
        self.level = level
        self.next_logger = None

    def set_next(self, next_logger):
        self.next_logger = next_logger
        return next_logger

    def log(self, level: LogLevel, message: str, appender: LogAppender):
        if level.value >= self.level.value:
            self.write(message, appender)
        if self.next_logger:
            self.next_logger.log(level, message, appender)

    @abstractmethod
    def write(self, message: str, appender: LogAppender):
        pass

