public class CoffeeMachine {
    private final Map<String, Integer> inventory = new ConcurrentHashMap<>();

    public CoffeeMachine() {
        inventory.put("water", 1000);
        inventory.put("milk", 500);
        inventory.put("coffee_beans", 300);
    }

    public synchronized boolean brewDrink(Beverage drink, int waterNeeded, int beansNeeded) {
        if (inventory.get("water") < waterNeeded || inventory.get("coffee_beans") < beansNeeded) {
            System.out.println("Insufficient supplies for: " + drink.getDescription());
            return false;
        }
        inventory.put("water", inventory.get("water") - waterNeeded);
        inventory.put("coffee_beans", inventory.get("coffee_beans") - beansNeeded);
        System.out.println("Brewed: " + drink.getDescription() + " ($" + drink.getCost() + ")");
        return true;
    }
}

