    @Override
    public void insertCoin(VendingMachine m, Coin coin) {
        m.addBalance(coin.value);
    }
    @Override
    public void selectItem(VendingMachine m, String code) {
        Item item = m.getItem(code);
        if (item != null && m.getBalance() >= item.getPrice()) {
            m.setSelectedItem(code);
            m.setState(m.getDispensingState());
            m.dispense();
        } else {
            System.out.println("Insufficient funds or invalid item.");
        }
    }
    @Override public void dispense(VendingMachine m) { System.out.println("Select item first."); }
    @Override
    public void cancelAndRefund(VendingMachine m) {
        System.out.println("Refunding $" + m.getBalance());
        m.resetBalance();
        m.setState(m.getIdleState());
    }
}

