    private final Random rand = new Random();
    @Override public int roll() { return rand.nextInt(6) + 1; }
}

public class Board {
    private final int totalCells;
    private final Map<Integer, Integer> specialJumps = new HashMap<>();

    public Board(int size) {
        this.totalCells = size;
    }

    public void addSnake(int head, int tail) {
        if (head <= tail) throw new IllegalArgumentException("Head must be > tail");
        specialJumps.put(head, tail);
    }

    public void addLadder(int start, int end) {
        if (start >= end) throw new IllegalArgumentException("Ladder start must be < end");
        specialJumps.put(start, end);
    }

    public int getFinalDestination(int position) {
        return specialJumps.getOrDefault(position, position);
    }

    public int getTotalCells() { return totalCells; }
}

public class SnakeAndLadderGame {
    private final Board board;
    private final Deque<String> players = new ArrayDeque<>();
    private final Map<String, Integer> playerPositions = new HashMap<>();
    private final DiceStrategy dice;

    public SnakeAndLadderGame(Board board, DiceStrategy dice, List<String> playerNames) {
        this.board = board;
        this.dice = dice;
        for (String p : playerNames) {
            players.add(p);
            playerPositions.put(p, 0);
        }
    }

    public boolean playNextTurn() {
        String player = players.pollFirst();
        int roll = dice.roll();
        int current = playerPositions.get(player);
        int next = current + roll;

        if (next <= board.getTotalCells()) {
            next = board.getFinalDestination(next);
            playerPositions.put(player, next);
            System.out.println(player + " rolled " + roll + " -> moved to " + next);
        }

        if (next == board.getTotalCells()) {
            System.out.println(player + " WON THE GAME!");
            return true;
        }

        players.addLast(player);
        return false;
    }
}

