        this.auctionId = id;
        this.reservePrice = reserve;
    }

    public void registerObserver(AuctionObserver obs) { observers.add(obs); }

    public synchronized boolean placeBid(String bidderId, double amount) {
        if (!isActive) return false;
        double minRequired = (highestBid == null) ? reservePrice : highestBid.amount + 5.0;
        if (amount < minRequired) return false;

        this.highestBid = new Bid(bidderId, amount);
        for (AuctionObserver obs : observers) {
            obs.onNewHighestBid(auctionId, highestBid);
        }
        return true;
    }

    public synchronized void closeAuction() {
        this.isActive = false;
        for (AuctionObserver obs : observers) {
            obs.onAuctionClosed(auctionId, highestBid);
        }
    }
}

