public class MoveCommand {
    private final Board board;
    private final Square from, to;
    private Piece capturedPiece;

    public MoveCommand(Board b, Square f, Square t) {
        this.board = b; this.from = f; this.to = t;
    }

    public boolean execute() {
        Piece piece = board.getPiece(from);
        if (piece == null || !piece.isValidMove(board, from, to)) return false;
        this.capturedPiece = board.getPiece(to);
        board.setPiece(to, piece);
        board.setPiece(from, null);
        return true;
    }

    public void undo() {
        Piece piece = board.getPiece(to);
        board.setPiece(from, piece);
        board.setPiece(to, capturedPiece);
    }
}

