    public void sendMessage(Message msg) {
        if (ConnectionManager.getInstance().isOnline(msg.recipientId)) {
            msg.status = MessageStatus.DELIVERED;
            System.out.println("Dispatched over WebSocket to " + msg.recipientId);
        } else {
            offlineMailbox.putIfAbsent(msg.recipientId, new ArrayList<>());
            offlineMailbox.get(msg.recipientId).add(msg);
            System.out.println("Queued in offline mailbox for " + msg.recipientId);
        }
    }
}

