import java.util.concurrent.ConcurrentHashMap;

public class StockItem {
    private final String sku;
    private int available;
    private int reserved;

    public StockItem(String sku, int initialQty) {
        this.sku = sku;
        this.available = initialQty;
        this.reserved = 0;
    }

    public synchronized boolean softReserve(int qty) {
        if (available < qty) return false;
        available -= qty;
        reserved += qty;
        return true;
    }

    public synchronized void commitReservation(int qty) {
        reserved -= qty;
    }

    public synchronized void cancelReservation(int qty) {
        reserved -= qty;
        available += qty;
    }

    public synchronized int getAvailable() { return available; }
    public String getSku() { return sku; }
}

