class StockItem {
private:
    std::string sku;
    int available;
    int reserved = 0;
    std::mutex mtx;
public:
    StockItem(std::string s, int qty) : sku(s), available(qty) {}

    bool reserve(int qty) {
        std::lock_guard<std::mutex> lock(mtx);
        if (available < qty) return false;
        available -= qty;
        reserved += qty;
        return true;
    }
};

