import java.util.*;

public class PoolRide {
    private final String rideId;
    private int availableSeats = 4;
    private final List<String> riderIds = new ArrayList<>();

    public PoolRide(String id) { this.rideId = id; }

    public synchronized boolean addRider(String riderId, int seatsNeeded) {
        if (availableSeats < seatsNeeded) return false;
        availableSeats -= seatsNeeded;
        riderIds.add(riderId);
        System.out.println("Rider " + riderId + " added to pool. Seats left: " + availableSeats);
        return true;
    }

    public synchronized void dropRider(String riderId, int seatsReleased) {
        riderIds.remove(riderId);
        availableSeats += seatsReleased;
    }
}

public interface DetourStrategy {
    boolean isDetourAcceptable(double originalDistance, double newTotalDistance, double maxDetourKm);
}

public class StandardDetourStrategy implements DetourStrategy {
    @Override
    public boolean isDetourAcceptable(double originalDist, double newTotalDist, double maxDetourKm) {
        return (newTotalDist - originalDist) <= maxDetourKm;
    }
}

