#include <iostream>
#include <vector>
#include <string>
#include <mutex>

class PoolRide {
private:
    std::string id;
    int availableSeats = 4;
    std::vector<std::string> riders;
    std::mutex mtx;
public:
    PoolRide(std::string i) : id(i) {}

    bool join(const std::string& riderId) {
        std::lock_guard<std::mutex> lock(mtx);
        if (availableSeats <= 0) return false;
        availableSeats--;
        riders.push_back(riderId);
        return true;
    }
};

